pub fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    a.into_iter()
        .map(|s| {
            // Split into lines; guarantee a non-empty inner Vec even if the string is empty.
            let mut parts: Vec<String> = if keepends {
                // Keep line ending characters.
                let mut out = Vec::new();
                let mut start = 0usize;
                let bytes = s.as_bytes();
                let mut i = 0usize;

                while i < bytes.len() {
                    match bytes[i] {
                        b'\n' => {
                            out.push(s[start..=i].to_string());
                            i += 1;
                            start = i;
                        }
                        b'\r' => {
                            if i + 1 < bytes.len() && bytes[i + 1] == b'\n' {
                                out.push(s[start..=i + 1].to_string());
                                i += 2;
                                start = i;
                            } else {
                                out.push(s[start..=i].to_string());
                                i += 1;
                                start = i;
                            }
                        }
                        _ => i += 1,
                    }
                }
                if start < s.len() {
                    out.push(s[start..].to_string());
                }
                out
            } else {
                // Do not keep line ending characters.
                let mut out = Vec::new();
                for line in s.split_inclusive(&['\n', '\r'][..]) {
                    let trimmed = line.trim_end_matches(&['\n', '\r'][..]);
                    out.push(trimmed.to_string());
                }
                if out.is_empty() && !s.is_empty() {
                    // No line ending chars; split_inclusive would return one element already,
                    // but keep this for completeness.
                    out.push(s);
                }
                out
            };

            if parts.is_empty() {
                parts.push(String::new());
            }
            parts
        })
        .collect()
}